// Pirámide Maya escalonada con escalinata frontal, plataforma y templo.
// Ejecuta (▶) con el Mundo abierto; elige un sitio despejado (centro ±16 en X/Z).
function buildMayanPyramid(originX, originY, originZ, options = {}) {
  const o = options;
  const baseSize    = o.baseSize    || 31;
  const levels      = o.levels      || 5;
  const levelHeight = o.levelHeight || 3;
  const stairWidth  = o.stairWidth  || 5;
  const stoneMat    = o.stoneMat    || 'stone';
  const stairMat    = o.stairMat    || 'smooth_stone';
  const halfStair = Math.floor(stairWidth / 2);
  let currentY = originY;
  let half = Math.floor(baseSize / 2);

  // 1) niveles escalonados (macizos) + escalinata frontal (cara +Z)
  for (let lvl = 0; lvl < levels; lvl++) {
    for (let h = 0; h < levelHeight; h++)
      for (let dx = -half; dx <= half; dx++)
        for (let dz = -half; dz <= half; dz++)
          setVoxel(originX + dx, currentY + h, originZ + dz, stoneMat);
    for (let s = 0; s < levelHeight; s++)
      for (let dx = -halfStair; dx <= halfStair; dx++)
        setVoxel(originX + dx, currentY + s, originZ + half + 1, stairMat);
    half -= 2;
    currentY += levelHeight;
  }

  // 2) plataforma superior
  const topHalf = half + 1;
  for (let dx = -topHalf; dx <= topHalf; dx++)
    for (let dz = -topHalf; dz <= topHalf; dz++)
      setVoxel(originX + dx, currentY, originZ + dz, stoneMat);
  currentY += 1;

  // 3) templo (muros stairMat, techo con voladizo stoneMat, portal en +Z)
  const templeHalf = Math.max(1, Math.floor(topHalf * 0.7));
  const templeHeight = 4;
  for (let h = 0; h < templeHeight; h++) {
    const isRoof = (h === templeHeight - 1);
    for (let dx = -templeHalf; dx <= templeHalf; dx++)
      for (let dz = -templeHalf; dz <= templeHalf; dz++) {
        const isWall = Math.abs(dx) === templeHalf || Math.abs(dz) === templeHalf;
        if (isRoof) setVoxel(originX + dx, currentY + h, originZ + dz, stoneMat);
        else if (isWall) {
          const isDoorway = dz === templeHalf && Math.abs(dx) <= 1 && h < 3;
          if (!isDoorway) setVoxel(originX + dx, currentY + h, originZ + dz, stairMat);
        }
      }
  }

  // 4) cornisa
  const roofY = currentY + templeHeight, roofHalf = templeHalf + 1;
  for (let dx = -roofHalf; dx <= roofHalf; dx++)
    for (let dz = -roofHalf; dz <= roofHalf; dz++)
      setVoxel(originX + dx, roofY, originZ + dz, stoneMat);
}

buildMayanPyramid(50, 15, 30, { stoneMat: 'arena', stairMat: 'adoquin' });
